#!/bin/ash
mkdir -p /mnt/server
cd /mnt/server

cat > geyser_notifier.py << 'EOF'
import json, os, time, urllib.request

env = os.environ.get
HOOK = env('WEBHOOK_URL', '').strip()
PROJECTS = [p.strip().lower() for p in env('PROJECTS', 'geyser').split(',') if p.strip()]
INTERVAL = max(60, int(env('CHECK_INTERVAL', '600')))
ROLE = env('MENTION_ROLE_ID', '').strip()
FIRST = env('NOTIFY_ON_FIRST_RUN', 'false').lower() == 'true'

# discord rejects the default python user agent
HEADERS = {'User-Agent': 'geyser-notifier'}
PURPUR = 'https://api.purpurmc.org/v2/purpur'


def log(msg):
    print(time.strftime('%H:%M:%S'), msg, flush=True)


def get(url):
    req = urllib.request.Request(url, headers=HEADERS)
    with urllib.request.urlopen(req, timeout=15) as r:
        return json.load(r)


def latest(project):
    # returns (key, version, changes)
    if project == 'purpur':
        ver = get(PURPUR)['versions'][-1]
        build = get(f'{PURPUR}/{ver}')['builds']['latest']
        try:
            commits = get(f'{PURPUR}/{ver}/{build}').get('commits', [])
            lines = [(c.get('description') or '').strip().splitlines() for c in commits]
            changes = [l[0] for l in lines if l]
        except Exception:
            changes = []
        return f'{ver}-{build}', ver, changes
    d = get(f'https://download.geysermc.org/v2/projects/{project}/versions/latest/builds/latest')
    return str(d['build']), d['version'], [c['summary'] for c in d.get('changes', [])]


def check(project):
    key, version, changes = latest(project)
    path = f'last_build_{project}.txt'
    last = open(path).read().strip() if os.path.exists(path) else None
    if last == key:
        return

    if last or FIRST:
        build = key.split('-')[-1]
        url = 'https://purpurmc.org/downloads' if project == 'purpur' else f'https://geysermc.org/download?project={project}'
        body = {'embeds': [{
            'title': f'{project.capitalize()} 新ビルド #{build}',
            'description': ('\n'.join('- ' + c for c in changes[:10]) or '変更履歴なし')[:4000],
            'url': url,
            'color': 0x5865F2,
            'fields': [{'name': 'バージョン', 'value': version, 'inline': True}],
        }]}
        if ROLE:
            body['content'] = f'<@&{ROLE}>'
            body['allowed_mentions'] = {'roles': [ROLE]}
        headers = {**HEADERS, 'Content-Type': 'application/json'}
        urllib.request.urlopen(urllib.request.Request(HOOK, json.dumps(body).encode(), headers), timeout=15)
        log(f'{project}: notified {key}')
    else:
        log(f'{project}: saved {key}')

    with open(path, 'w') as f:
        f.write(key)


if not HOOK:
    raise SystemExit('WEBHOOK_URL is not set')

log('notifier started')
while True:
    for p in PROJECTS:
        try:
            check(p)
        except Exception as e:
            log(f'{p}: {e}')
    time.sleep(INTERVAL)
EOF

echo "Done."
